class SumThread extends Thread {
    int[] arr;
    int start, end;
    int sum = 0;

    SumThread(int[] arr, int start, int end) {
        this.arr = arr;
        this.start = start;
        this.end = end;
    }

    public void run() {
        for(int i = start; i < end; i++) {
            sum += arr[i];
        }
    }

    int getSum() {
        return sum;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        int[] arr = {1,2,3,4,5,6,7,8};

        SumThread t1 = new SumThread(arr, 0, 4);
        SumThread t2 = new SumThread(arr, 4, 8);

        t1.start();
        t2.start();

        t1.join();
        t2.join();

        int total = t1.getSum() + t2.getSum();
        System.out.println("Total Sum: " + total);
    }
}

