import java.util.*;

class Student {
    String name;
    int marks;

    Student(String name, int marks) {
        this.name = name;
        this.marks = marks;
    }
}

public class Main {
    public static void main(String[] args) {
        List<Student> list = Arrays.asList(
            new Student("Alice", 80),
            new Student("Bob", 70),
            new Student("Charlie", 90)
        );

        list.sort(Comparator.comparingInt(s -> s.marks));

        list.forEach(s -> System.out.print(s.name + " " + s.marks + " "));
    }
}

import java.util.*;

class Employee {
    String dept;
    int salary;

    Employee(String d, int s) {
        dept = d;
        salary = s;
    }
}

public class Main {
    public static void main(String[] args) {
        List<Employee> list = Arrays.asList(
            new Employee("HR", 50000),
            new Employee("IT", 60000),
            new Employee("HR", 40000)
        );

        list.sort(
            Comparator.comparing((Employee e) -> e.dept)
                      .thenComparingInt(e -> e.salary)
        );

        list.forEach(e -> System.out.print(e.dept + " " + e.salary + " "));
    }
}

