import java.util.*;

class Address {
    String city;
    Address(String c) { city = c; }
}

class User {
    Address address;
    User(Address a) { address = a; }
}

public class Main {
    public static void main(String[] args) {
        User user = new User(new Address("Delhi"));

        String city = Optional.ofNullable(user)
            .map(u -> u.address)
            .map(a -> a.city)
            .orElse("Unknown");

        System.out.println(city);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        String primary = null;
        String secondary = "Python";
        String def = "Code";

        String result = Optional.ofNullable(primary)
            .or(() -> Optional.ofNullable(secondary))
            .or(() -> Optional.ofNullable(def))
            .orElse("No Data");

        System.out.println(result);
    }
}

import java.util.*;

class Employee {
    Integer salary;
    Employee(Integer s) { salary = s; }
}

class Department {
    Employee emp;
    Department(Employee e) { emp = e; }
}

class Company {
    Department dept;
    Company(Department d) { dept = d; }
}

public class Main {
    public static void main(String[] args) {
        Company company = new Company(new Department(new Employee(50000)));

        int salary = Optional.ofNullable(company)
            .map(c -> c.dept)
            .map(d -> d.emp)
            .map(e -> e.salary)
            .orElse(0);

        System.out.println(salary);
    }
}

